mapper.select:
select d.id as detailId, r.id as registrationId, a.id as activityId, a.topic_id as topicId, coalesce(a.name, r.activity_title) as activityTitle, r.ticket_name as ticketName, coalesce(d.update_time, d.create_time) as occurredAt, d.settlement_amount as feeAmount, o.fixed_fee as unitFee, (select coalesce(sum(adj.settlement_amount), 0) from settlement_detail adj join refund_application ra on ra.id = adj.source_id and ra.source_type = 'registration' where adj.source_type = 'refund' and adj.status = 1 and adj.receiver_type = 'coop_merchant' and adj.receiver_id = d.receiver_id and ra.source_id = r.id) as clawbackAmount, d.status as status from settlement_detail d join cms_registration r on r.id = d.source_id join cms_activity a on a.id = r.owner_id left join settlement_claim c on c.id = d.claim_id left join coop_order o on c.source_contract_type = 'COOP_ORDER' and o.id = c.source_contract_id where d.source_type = 'registration' and d.receiver_type = 'coop_merchant' and d.receiver_id = #{merchantMemberId} and d.status = 1 and r.owner_type = 2
and a.id = #{activityId}
order by d.id desc

select gv.activity_id as activityId, gv.merchant_member_id as merchantMemberId, a.end_date as endDate, o.fixed_fee * ( select coalesce(sum(case when seat.n > 0 then seat.n else coalesce(r.order_num, 1) end), 0) from cms_registration r left join (select s.registration_id, count(1) as n from cms_registration_seat s where s.status = 1 group by s.registration_id) seat on seat.registration_id = r.id where r.owner_type = 2 and r.owner_id = gv.activity_id and r.payment_status = 2 and r.registration_status = 2 and and not exists ( select 1 from refund_application ra where ra.source_type = 'registration' and ra.source_id = r.id and ra.status = 1 and ra.del_flag = 0) ) as amount from coop_group_verify gv join cms_activity a on a.id = gv.activity_id join coop_order o on o.id = gv.coop_order_id and o.to_type = 'merchant' and o.to_id = gv.merchant_member_id and o.status = 0 and o.del_flag = 0 and o.share_mode = 2 where a.is_settlement = 0 and a.del_flag = 0 and a.status = 1 and a.club_id > 0
and gv.merchant_member_id = #{merchantMemberId}
and gv.activity_id in #{activityId}
order by gv.activity_id, gv.merchant_member_id
